Based on all the information from SceneDesignerAgent's sandbox report and CommonSenseAgent's feedback, here are my milestone rules. I'm carefully using the valid rule types from the specification.

```json
{
  "milestones": [
    {
      "task": "find cyan_stained_glass",
      "milestone_id": "find_cyan_stained_glass",
      "description": "Uses position_near_with_facing because this is a find/locate task. The cyan stained glass panel is centered around (~-2, 2, 5) relative to spawn. The player must navigate near it and face it to demonstrate they've found it. max_distance=16 and facing_tolerance=60 are used as defaults since the glass is visible from moderate distance.",
      "rules": [
        {
          "type": "position_near_with_facing",
          "params": {
            "target": [-2, 2, 5],
            "max_distance": 16,
            "facing_tolerance": 60,
            "coordinate_frame": "spawn_relative"
          }
        }
      ]
    },
    {
      "task": "mine lime_stained_glass",
      "milestone_id": "mine_lime_stained_glass",
      "description": "Uses count_in_box_at_most (kind=block) to detect that at least one lime_stained_glass block has been removed from the front wall. The original wall has 9 lime glass blocks at x=-1..1, y=1..3, z=8. We check that the count is at most 8 (meaning at least 1 was mined). This is preferred over inventory_has because stained glass does NOT drop itself when broken without Silk Touch — the player gets nothing in inventory. A generous box of ±3 around the wall center is used.",
      "rules": [
        {
          "type": "count_in_box_at_most",
          "params": {
            "kind": "block",
            "object": "lime_stained_glass",
            "min": [-4, -1, 5],
            "max": [4, 6, 11],
            "max_count": 8,
            "coordinate_frame": "spawn_relative"
          }
        }
      ]
    },
    {
      "task": "mine dark_oak_door",
      "milestone_id": "mine_dark_oak_door",
      "description": "Uses inventory_has because dark oak doors DO drop themselves as an item when broken by hand (unlike glass). The door at (0, 1-2, 10) will drop 1 dark_oak_door item into the player's inventory when either half is broken. This is the most reliable check since the item ends up in inventory.",
      "rules": [
        {
          "type": "inventory_has",
          "params": {
            "item": "dark_oak_door",
            "min_count": 1
          }
        }
      ]
    }
  ]
